let R0 = 3;
let pc = 104;        // start at the test
let bodyRuns = 0;
let backwardJumps = 0;

// hand-rolled machine: addresses 104=CMP/JE, 112=SUB, 116=JUMP back
while (true) {
  if (pc === 104) {           // CMP R0,0 + JE 120
    if (R0 === 0) { pc = 120; } else { pc = 112; }
  } else if (pc === 112) {     // SUB R0,1 (the body)
    R0 = R0 - 1;
    bodyRuns++;
    pc = 116;
  } else if (pc === 116) {     // JUMP 104 (the backward jump)
    backwardJumps++;
    pc = 104;                  // PC <- 104, smaller address = backward
  } else if (pc === 120) {     // loop exit
    break;
  }
}

console.log('bodyRuns=' + bodyRuns + ' backwardJumps=' + backwardJumps + ' R0=' + R0);
